# Code Scanner Module - Automated security and quality scanning\nimport ast\nimport re\nfrom typing import List, Dict, Set\n\nclass CodeScanner:\n    def __init__(self):\n        self.vulnerability_patterns = {\n            'sql_injection': r'.*execute\\(.*\\%.*\\)',\n            'xss': r'.*innerHTML.*',\n            'insecure_random': r'random\\.random\\(\\)',\n            'hardcoded_secrets': r'(password|secret|key)\\s*=\\s*[\\'\\"].*[\\'\\"]'\n        }\n        self.quality_metrics = {\n            'complexity': 0,\n            'maintainability': 0,\n            'security_score': 0\n        }\n\n    def scan_code(self, code_string: str) -> Dict:\n        \"\"\"Perform comprehensive code scan for vulnerabilities and quality\"\"\"\n        results = {\n            'vulnerabilities': [],\n            'quality_metrics': {},\n            'recommendations': []\n        }\n\n        # Parse code into AST\n        try:\n            tree = ast.parse(code_string)\n        except SyntaxError as e:\n            results['vulnerabilities'].append({\n                'type': 'syntax_error',\n                'location': f'Line {e.lineno}',\n                'description': str(e)\n            })\n            return results\n\n        # Scan for known vulnerability patterns\n        for vuln_type, pattern in self.vulnerability_patterns.items():\n            matches = re.finditer(pattern, code_string, re.MULTILINE)\n            for match in matches:\n                results['vulnerabilities'].append({\n                    'type': vuln_type,\n                    'location': f'Line {code_string.count(chr(10), 0, match.start()) + 1}',\n                    'code': match.group(0)\n                })\n\n        # Calculate code quality metrics\n        results['quality_metrics'] = self._calculate_metrics(tree)\n\n        # Generate recommendations\n        results['recommendations'] = self._generate_recommendations(results)\n\n        return results\n\n    def _calculate_metrics(self, tree: ast.AST) -> Dict:\n        \"\"\"Calculate various code quality metrics\"\"\"\n        metrics = self.quality_metrics.copy()\n        \n        # Complexity calculation\n        class ComplexityVisitor(ast.NodeVisitor):\n            def __init__(self):\n                self.complexity = 0\n\n            def visit_If(self, node):\n                self.complexity += 1\n                self.generic_visit(node)\n\n            def visit_For(self, node):\n                self.complexity += 1\n                self.generic_visit(node)\n\n            def visit_While(self, node):\n                self.complexity += 1\n                self.generic_visit(node)\n\n        visitor = ComplexityVisitor()\n        visitor.visit(tree)\n        metrics['complexity'] = visitor.complexity\n\n        # Calculate maintainability index\n        loc = len(ast.unparse(tree).split('\\n'))\n        metrics['maintainability'] = max(0, (100 - metrics['complexity'] * 0.5 - loc * 0.1))\n\n        # Calculate security score\n        metrics['security_score'] = 100 - (len(self._find_security_issues(tree)) * 10)\n\n        return metrics\n\n    def _find_security_issues(self, tree: ast.AST) -> List[Dict]:\n        \"\"\"Find potential security issues in the AST\"\"\"\n        issues = []\n        \n        class SecurityVisitor(ast.NodeVisitor):\n            def __init__(self):\n                self.issues = []\n\n            def visit_Call(self, node):\n                if isinstance(node.func, ast.Name):\n                    if node.func.id in ['eval', 'exec']:\n                        self.issues.append({\n                            'type': 'dangerous_function',\n                            'name': node.func.id\n                        })\n                self.generic_visit(node)\n\n        visitor = SecurityVisitor()\n        visitor.visit(tree)\n        return visitor.issues\n\n    def _generate_recommendations(self, scan_results: Dict) -> List[str]:\n        \"\"\"Generate improvement recommendations based on scan results\"\"\"\n        recommendations = []\n\n        if scan_results['quality_metrics']['complexity'] > 10:\n            recommendations.append(\n                'Consider breaking down complex functions into smaller, more manageable pieces'\n            )\n\n        if scan_results['quality_metrics']['maintainability'] < 65:\n            recommendations.append(\n                'Code maintainability is low. Consider adding documentation and simplifying logic'\n            )\n\n        if scan_results['quality_metrics']['security_score'] < 80:\n            recommendations.append(\n                'Security score is concerning. Review and address identified vulnerabilities'\n            )\n\n        return recommendations